export const products: StaticProduct[] = [
  ..._products_0,
  ..._products_1,
  ..._products_2,
  ..._products_3,
  ..._products_4,
];

// Helper function to get products by category
export function getProductsByCategory(categorySlug: string): StaticProduct[] {
  return products.filter((p) => p.category === categorySlug);
}

// Helper function to get products by subcategory
export function getProductsBySubcategory(subcategorySlug: string): StaticProduct[] {
  return products.filter((p) => p.subcategory === subcategorySlug);
}

// Helper function to get product by slug
export function getProductBySlug(slug: string): StaticProduct | undefined {
  return products.find((p) => p.slug === slug);
}

// Helper function to get all unique brands from products
export function getAllBrands(): string[] {
  const brands = new Set(products.map((p) => p.brand));
  return Array.from(brands).sort();
}
